TOP=[ # code, naam, refs, dag (rooster+rituelendag+eten), intiem (intimiteit, rivaliteit, geheim)
('ithrael','Hoge Moeder Ithrael (Orde)','PER-ithrael','Staat op voor de klok van vier, leest de lekmeldingen, ontvangt drie Moeders, eet om twaalf alleen brood met zaadas en witte vis. Rituelendag: Lege Dag-voorbereiding, zegening van de kluislamp, wijding in de avond. Eet nooit wat een ander proefde zonder proefster.','Intimiteit: één vertrouwde zuster, nooit een man in haar cel. Rivaliteit: Moeder Vessa en Selvine Varenne. Geheim: haar staf dooft en ze kent een deel van het logboek van de Ysa.'),
('selvine','Vrouwe Selvine Varenne','PER-selvine;HUI-varenne','Beurs om negen, lunch met schuldeisers, middagen met gaven-mannen in de keurkamer. Rituelendag: de jaarlijkse Veiling, met parelmoeren beursbrieven. Eet zoet, oesters en dure vleesgerechten in kleine porties.','Intimiteit: wisselende minnaressen en één vaste man die ze huurt. Rivaliteit: Ithrael en Ondessa Mirre. Geheim: Varenne is failliet sinds de crash van 762.'),
('kaldra','Huis Kaldra (Krijgsvrouwe van Kaldra)','HUI-kaldra','Opstaan voor de dageraad, oefening met het garnizoen, bevelsraad, Strijdontvangst voor de slag. Rituelendag: de maandelijkse Strijdzaad-uitdeling aan de tempelwacht. Eet soldatenvoer met veel vlees.','Intimiteit: krijgsvrouwen delen een gaven-man voor de slag (instemmend). Rivaliteit: de Orde en de schande van Sorre (722). Geheim: Kaldra-vrouwen in de tempelwacht rapporteren aan haar.'),
('ondessa','Kapitein-Vrouwe Ondessa Mirre','PER-ondessa;HUI-mirre','Leeft volgens het getij; nachten op zee, dagen in pakhuizen. Rituelendag: de Knoopnacht, wanneer schippers trouw zweren. Eet vis, zout brood, gesmokkelde wijn.','Intimiteit: een gesmokkelde man in haar kajuit, die vrij is te gaan. Rivaliteit: Varenne en de Orde-havenwacht. Geheim: ze vaart soms tot de rand van de Leegte.'),
('khaled','Zonvorst Khaled-Ir (Qesh)','PER-khaled-profiel;HUI-qesh','Ochtendaudiëntie in het Zonnepaleis, middagrust, avond met gezanten van Kharvos en de Orde (apart). Rituelendag: de Zonnekroning. Eet dadels, lamsvlees en koude yoghurt; proefsters uit de Ishvar.','Intimiteit: een paarhuwelijk volgens oud Qesh-recht en een harem waarvan de bellen betekenis hebben. Rivaliteit: Kharvos en de Orde tegelijk. Geheim: zijn zonnekroon is vervalst.'),
('hask','Koning van Kharvos','REG-kharvos','Krijgsraad, jachten, mannenraad. Rituelendag: de Mannendag waarin vrijheid gevierd wordt. Eet wild en bier.','Intimiteit: in Kharvos wonen mannen bij één vrouw of meerdere naar keuze; de koning houdt vrouwen als gijzelaars (donker thema). Rivaliteit: de Orde. Geheim: Kharvos valt deels buiten het Zegel en kent dus een gewone verhouding.'),
('morvane','Morvane-ir, duister gaven-heer','PER-morvane-profiel','Slaapt overdag, hof bij nacht, lading in de avond. Rituelendag: de Bloednacht-herdenking. Eet rauw en weinig.','Intimiteit: gebonden vrouwen (donker thema, gelabeld). Rivaliteit: de Orde en Aeron-as. Geheim: hij weet dat de Vonk een ontwerp is.'),
('borga','Borga Gildemoeder (Dhurn)','PER-dhurn-borga','Gildenraad bij het smeltvuur, middagbad, avond veilingen. Rituelendag: de Steendag. Eet zout vlees en bier uit rotsgist.','Intimiteit: de Vreemdelingsnacht in de baden. Rivaliteit: Orvald en de Orde. Geheim: haar handen openen de Sprekende Kluis.'),
('korfmoeder','De Korfmoeder van de Kluwers','VOLK-kluwer','Wordt gevoed, hoort de korf, beslist bij zonsondergang. Rituelendag: de Waxnacht. Eet honing en larvenpap (dieren alleen als voedsel).','Intimiteit: gekozen gezellen. Rivaliteit: de Myrrhen. Geheim: de korf liegt soms tegen haar.'),
('ysmeriel','Oudste Ysmeriel (Aelthir)','VOLK-aelthir','Dagen duren lang: zingen, tellen aan de Rekening, één beslissing per maand. Rituelendag: het eeuwfeest. Eet bloemen en hars.','Intimiteit: verboden liefde voor een sterfelijke Stille Zuster. Rivaliteit: de schaduw van Ileth. Geheim: zij weet dat de ster ooit een schip was.'),
('karruk','Opperhoofd van de Karrûk','VOLK-karrûk','Training, kampioensgevechten, raad aan het vuur. Rituelendag: het Kampioensgevecht. Eet geroosterd vlees en vergist melk.','Intimiteit: ontlading als heilige plicht. Rivaliteit: Asha Driekerf. Geheim: het gevecht van Asha was gekocht.'),
('skerra','Klifvorstin van de Skerra','VOLK-skerra','Vliegt bij dageraad, ontvangt berichten, oordeelt op de rots. Rituelendag: de Nestkroning. Eet vis en vogeleieren.','Intimiteit: hoog in de nesten, alleen voor wie mag vliegen. Rivaliteit: Hesk Klifmeester. Geheim: het nest is leeg.'),
]
MID=[('ambacht-saelith','Kleermaaksters en glasblazers van Saelith','Werkdag van zes tot zes; gildebijeenkomst op de vijfde dag; gunstbrieven als bonus. Haak: een kleermaakster naait vervalste sjerpen.'),
('handelaar','Handelaarsters en zaadmakelaars','Markt bij het getij, schuldboeken bij kaarslicht. Haak: een makelaar verkoopt een gaven-man twee keer.'),
('heelster','Heelsters en kweeksters','Rondes langs kraambedden en stallen; heelslijm in potten. Haak: een heelster ziet de eerste lekgeboorte.'),
('schrijfster','Registerschrijfsters','Kopieerwerk in de kelder, zwarte handen, zwijgplicht. Haak: een schrijfster vindt Annike\'s vervalsing.'),
('herbergier','Herbergiersters','Bel bij de deur die zingt voor gaven-mannen; kamers per nacht of per beurt. Haak: een herbergierster verbergt een vluchteling.'),
('laadster','Laadsters','Werk in de Registerkamer; lading in voorwerpen. Haak: een laadster zet een deel apart voor de rebellen.'),
('dhurn-smid','Dhurn-smeden en glasblazers','Werken in ploegen bij het smeltvuur; baden na de dienst. Haak: een glasblazer ziet een gezicht in het glas.'),
('boerin','Ambergaardse boerinnen met land','Oogst, register, Oogstnacht-strik. Haak: een boerin weigert haar man te delen.'),
('schipper','Mirre-schippers en loodsen','Varen, ruilen, zwijgen. Haak: een loods hoort een worm zingen in de Leegte.'),
('tempelwacht','Tempelwachtsters','Diensten in roosters, maandelijks Strijdzaad. Haak: een wachtster rapporteert aan Kaldra.')]
LAAG=[('mijn','Mijnwerkers en mijnwerksters van Hoogvrouwe','Twaalf uur onder de grond, mijnlampen, steenkoorts; samen baden. Eten: rotsgistbrood. Haak: Runa steelt splinters.'),
('stal','Stalmannen van de melkstallen','Een rooster van melkbeurten, registerketting, slapen op stro. Eten: zaadversterkend brij. Haak: een stalman leert lezen en ontdekt zijn eigen lijn.'),
('stalvrouw','Stalverzorgsters','Voeden, wassen en tellen; ze zien wie uitgeput raakt. Haak: een verzorgster wordt verliefd op een stalman (instemmend, verboden).'),
('haven','Havenwerksters van Zoutkust','Laden en lossen, haken, zout; kroeg na het getij. Haak: een staking op de kades.'),
('rand','Randvolk en askouden aan de rand','Jagen, ruilen, schuilen voor de Asgrenswacht. Haak: een randvrouw vindt een kluisstuk.'),
('dienst','Dienstmeiden en paleiswacht','Voor de dageraad op, slapen bij de keuken, zien alles. Haak: een dienstmeid hoort een kluislamp zoemen.'),
('zout','Zoutwerksters','Pannen, brandende huid, liederen tegen de belasting. Haak: de zoutopstand herhaalt zich.'),
('grauwen-dorp','Grauwen in de randdorpen','Zorg voor elkaar, de Ontsluiering, verbergen van Lijngravers. Haak: Mott wordt verraden.'),
('vluchteling','Vluchtelingen uit Kharvos-gebied','Kampen, rantsoen, geen register. Haak: een vluchtelinge is een Kharvos-spion.'),
('bedelaar','Bedelaarsters en lekmoeders','Moeders van lekgeboren zonen die stil volwassen werden, zoeken hen. Haak: een moeder vindt haar zoon als stalman.')]
SUB=[('feesters','De Lampennachters (feesters)','Groenmuil-feesten, maskers, anonimiteit, risico op verwantschap; alles tussen instemmende volwassenen.'),
('kunstenaars','De Lichtschilders (kunstenaars)','Schilderen met zegelglas op huid; tentoonstellingen bij nacht; de Orde verbiedt naakt-zegelkunst.'),
('smokkelaars','De Kielbroeders (smokkelaars)','Mirre-smokkelaars van mannen, lading en grijswortel; codes in knopen.'),
('sekte-kluis','De Koudhanden (sekte)','Vereren de koude huizen en machines als ware goden; ze bidden tot de Stemschijf. Weten niet dat ze de oude Corran-partij voortzetten.'),
('fetisj','De Ketenclub van Zoutkust (fetisjclub)','Publieke ketenwake als spel tussen instemmende volwassenen; codewoorden en een stopbel.'),
('zangers','De Klifzangers','Zwervende zangeressen die het nieuws zingen; verbergen berichten in liederen.'),
('vervalsers','De Inktgilde (vervalsers)','Opvolgers van het vervalsersgilde van 680; maken merken en gunstbrieven.'),
('vluchtelingen','De Stille Treinen (vluchtelingen)','Netwerk dat vrouwen en mannen uit gesloten fokprogramma\'s haalt.'),
('lustwijn','De Wijnzusters','Drinken ladingswijn; vieren extase; raken verslaafd aan ontvangst.'),
('ishvar-blinden','De Blinden','Mensen die zich laten verblinden voor zegelgloed om "eerlijk" lief te hebben.'),
('lekkinderen','De Lekbroeders','Volwassen lekgeboren mannen die samen leven, buiten het register.'),
('vleeskunst','De Groeiers','Lichaamsbouwers die zich met bio-techniek laten aanpassen; mode van vlees.'),
('wormvaarders','De Wormvaarders','Navigators en hun bemanning, half verwilderd; trouw aan hun worm.'),
('annalen','De Leesters','Stille lezers die met zwarte handen de echte annalen kopiëren.')]
REBEL=[('lege-hand','De Lege Hand (anarchisten)','Doel: het register vernietigen. Methode: brandstichting in registerkelders. Leiders: Wanne Asvoet. Eten: gestolen tempelbrood. Kleding: zwarte handschoenen, geen sjerp. Liefde: vrije keuze, geen register, ook verwanten-angst. Verraad: een infiltrant van de Stille Hand. Haak (thriller): de brand in de kelder van Saelith.'),
('grijswortel','Het Grijswortelnetwerk','Doel: iedereen kunnen ontbinden. Methode: grijswortel smokkelen. Leiders: Heelster Moira Tes. Eten: bitterbrood. Kleding: groene draad in de zoom. Liefde: tederheid, nooit binding. Verraad: een leverancier van Varenne. Haak (romance): een gebonden hofdame en haar smokkelaarster.'),
('stalopstand','De Staljongens van 801 (volwassen stalmannen)','Doel: mannen uit de stallen bevrijden. Methode: sabotage van melkroosters. Leiders: Bram Hoeve. Eten: brij. Kleding: gebroken registerkettingen. Liefde: in het geheim met verzorgsters. Verraad: een stalman die beloond wordt met een gunstbrief. Haak (intrige): wie verkocht het plan.'),
('koudhanden-militant','De Kernrovers','Doel: kluismachines stelen om de Orde te breken. Methode: inbraken met nagemaakte paneelsleutels. Leiders: Ostra\'s erfgename Ylse Kern. Eten: wat ze ruilen. Kleding: metaalschubben. Liefde: snel en gevaarlijk. Verraad: Kluiswachter als dubbelspion. Haak (thriller): de lichtlans.'),
('dochters-wraak','De Wraak van Lisk','Doel: de Dochters bevrijden uit de steen. Methode: zegelankers stelen. Leiders: een ex-tempelwacht, Senna. Eten: vasten op heilige dagen. Kleding: rood met wit. Liefde: alleen na eed. Verraad: een Moeder die mee doet. Haak (horror): een anker weghalen verzwakt het Zegel.'),
('orrim-terug','De Voorouderstam (Orrim)','Doel: de Orrim-lichamen uit het Zegel terug. Methode: aanvallen op oogstkampen. Leiders: Sha Kristalader. Eten: zand en zout. Kleding: geen. Liefde: Sha en een mensenvrouw. Verraad: een Orde-gezant belooft vrede. Haak (oorlog): 801-ultimatum.'),
('stille-pen','De Stille Pen','Doel: de waarheid publiceren. Methode: pamfletten, liederen, gekopieerde annalen. Leiders: Marit Schrijfster (Annike). Eten: wat de herberg geeft. Kleding: inktvlekken. Liefde: Annike en Joost. Verraad: drukker verkoopt aan Vessa. Haak (intrige): het logboek van de Ysa.'),
('kharvos-vijfde','De Vijfde Kolonne (Kharvos-rebellen)','Doel: de Orde omverwerpen met Kharvos-steun. Methode: spionage, ronselen. Leiders: gezant Torvin. Eten: Kharvos-bier. Kleding: als gewone burgers. Liefde: als wapen, verleiding van tempelwachtsters (instemmend, met bedrog). Verraad: Khaled-Ir speelt dubbel. Haak (thriller): de inval.'),
('vrije-moeders','De Vrije Moeders','Doel: kiezen met wie je een kind krijgt. Methode: verborgen Oogstnachten buiten het register. Leiders: Edda van Ambergaard. Eten: gedeelde maaltijden. Kleding: strik in het haar ook overdag. Liefde: vrij, met eigen namenlijst tegen inteelt. Verraad: een vervalster. Haak (erotiek/romance): een Oogstnacht met een vreemdeling.')]
MID+=[('kluiswachter','Kluiswachters (lage rang)','Dienst in koude gangen, zwijgplicht, zwarte handschoenen; erven het ambt via Hesta Kaels lijn zonder het te weten. Haak: een wachter hoort de stem in de kluis zijn naam zeggen.'),
('navigatorfamilie','Families van wormnavigators','Leven aan de havens van de Leegte, rouwen bij elke vaart. Haak: een navigator keert terug met een vreemde in het ruim.'),
('muzikant','Hofmuzikanten en klokgieters','Spelen bij Ontvangsten; kennen alle geheimen van de slaapkamers. Haak: een lied verraadt een affaire.'),
('proefster','Proefsters aan de hoven','Proeven elk gerecht van heersers; goed betaald, kort leven. Haak: een proefster kiest wie mag sterven.')]
LAAG+=[('stalreus','Stalreuzen-dragers','Mismaakte sterke mannen uit gesloten fokprogramma\'s, verhuurd als sjouwers. Haak: een stalreus redt een Moeder.'),
('wasvrouw','Wasvrouwen van het hof','Wassen lakens van Ontvangsten; lezen vlekken als nieuws. Haak: Ysel\'s erfgenamen.'),
('askoude-ruil','Askoude-ruilers','Ruilen met askouden aan de rand: brood voor kluisresten. Haak: een askoude spreekt de dode taal.'),
('zoutlijk-gravers','Grafdelvers van de Zoutkust','Begraven zoutlijken, verkopen hun spullen. Haak: een lijk draagt een paneelsleutel.')]
